shell_commands:
node -e "
import('node:fs').then(fs => {
  const pkg = './node_modules/@re-cinq/eslint-plugin-re-lint';
  console.log(fs.readdirSync(pkg, {recursive: true}).filter(f => f.endsWith('.js')));
});
"

node -e "
import('node:fs').then(fs => {
  const pkg = './node_modules/@re-cinq/eslint-plugin-re-lint';
  console.log(fs.readFileSync(pkg + '/package.json', 'utf8'));
  console.log(fs.readdirSync(pkg, {recursive: true}));
});
"

node -e "
import('node:fs').then(fs => {
  const pkg = './node_modules/@re-cinq/eslint-plugin-re-lint';
  for (const f of [
    'dist/rules/require-colocated-tests.mjs',
    'dist/rules/test-imports-its-subject.mjs',
    'dist/rules/require-spec-link.mjs',
    'dist/rules/max-expects.mjs',
    'dist/rules/require-status-matches-coverage.mjs',
    'dist/vendor/spec/test-paths.js'
  ]) {
    console.log('=== ' + f + ' ===');
    console.log(fs.readFileSync(pkg + '/' + f, 'utf8'));
  }
});
"

